import zipfile
import xml.etree.ElementTree as ET

NS = {
    "main": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    "rel": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
    "pkgrel": "http://schemas.openxmlformats.org/package/2006/relationships",
}

def col_letter_to_idx(letter):
    idx = 0
    for ch in letter:
        idx = idx * 26 + (ord(ch) - ord("A") + 1)
    return idx - 1

def col_idx_to_letter(idx):
    s = ""
    idx += 1
    while idx > 0:
        idx, rem = divmod(idx - 1, 26)
        s = chr(ord("A") + rem) + s
    return s

path = "budget.xlsx"
with zipfile.ZipFile(path) as z:
    print("=== Files in archive ===")
    for n in z.namelist():
        print(" ", n)

    # workbook.xml -> sheet list + relationships
    wb_root = ET.fromstring(z.read("xl/workbook.xml"))
    rels_root = ET.fromstring(z.read("xl/_rels/workbook.xml.rels"))
    rels = {}
    for rel in rels_root.findall("pkgrel:Relationship", NS):
        rels[rel.get("Id")] = rel.get("Target")

    sheets = []
    for sh in wb_root.find("main:sheets", NS):
        sheets.append((sh.get("name"), sh.get("sheetId"), sh.get("r:id")))
    print("\n=== Sheets ===", sheets)

    # shared strings
    shared = []
    if "xl/sharedStrings.xml" in z.namelist():
        ss_root = ET.fromstring(z.read("xl/sharedStrings.xml"))
        for si in ss_root.findall("main:si", NS):
            text = "".join(t.text or "" for t in si.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
            shared.append(text)

    for name, sid, rid in sheets:
        target = rels.get(rid)
        if target.startswith("/"):
            target = target.lstrip("/")
        elif not target.startswith("xl/"):
            target = "xl/" + target
        print(f"\n=== Sheet '{name}' content (target={target}) ===")
        sheet_root = ET.fromstring(z.read(target))
        sd = sheet_root.find("main:sheetData", NS)
        for row in sd.findall("main:row", NS):
            r = int(row.get("r"))
            for c in row.findall("main:c", NS):
                ref = c.get("r")
                t = c.get("t")
                v = c.find("main:v", NS)
                isel = c.find("main:is", NS)
                raw = None
                if t == "s" and v is not None:
                    raw = shared[int(v.text)]
                elif t == "inlineStr" and isel is not None:
                    raw = "".join(x.text or "" for x in isel.iter("{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t"))
                elif v is not None:
                    raw = v.text
                print(f"  {ref}: type={t} value={raw!r}")

